const { pathToFileURL } = require("url");
const assert = require("assert");
const root = process.cwd();
const S = __dirname;
(async () => {
  for (const [src, dst] of [["src/module.ts", "orig.mjs"], ["out/module.ts", "new.mjs"]]) {
    await build({ entryPoints: [path.join(root, src)], bundle: true, format: "esm", platform: "node",
      outfile: path.join(S, dst), logLevel: "error", absWorkingDir: root, nodePaths: [path.join(root, "node_modules")] });
  }
  const o = await import(pathToFileURL(path.join(S, "orig.mjs")).href);
  const n = await import(pathToFileURL(path.join(S, "new.mjs")).href);
  let cnt = 0;
  const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
  const names = ["alpha", "bravo", "charlie", "delta", "echo"];
  const dcases = [{ choi: 48, kim: 81, park: 98 }, { jung: -2, lee: 1 }, {}];
  for (let i = 0; i < 2000; i++) { const k = rnd(0, 5), ob = {}; for (let j = 0; j < k; j++) ob[names[rnd(0, 4)] + j] = rnd(-5, 99); dcases.push(ob); }
  for (const c of dcases) { assert.deepStrictEqual(n.doubled(c), o.doubled(c)); cnt++; }
  const rnames = ["choi", "lee", "park", "kim", "jung"];
  const rcases = [[{ id: 6, name: "choi", age: 21 }, { id: 5, name: "lee", age: 45 }, { id: 9, name: "park", age: 29 }, { id: 6, name: "choi", age: 44 }, { id: 8, name: "kim", age: 36 }, { id: 0, name: "kim", age: 38 }, { id: 1, name: "choi", age: 54 }, { id: 2, name: "park", age: 36 }], []];
  for (let i = 0; i < 2000; i++) { const L = rnd(0, 12), a = []; for (let j = 0; j < L; j++) a.push({ id: rnd(0, 9), name: rnames[rnd(0, 4)], age: rnd(18, 60) }); rcases.push(a); }
  for (const c of rcases) { assert.deepStrictEqual(n.byNameKey(c), o.byNameKey(c)); cnt++; }
  const vcases = [[2, 5, 7, 14, 20], [5, 7, 9, 11, 12, 13, 15, 17, 19], []];
  for (let i = 0; i < 2000; i++) { const L = rnd(0, 20), a = []; for (let j = 0; j < L; j++) a.push(rnd(-5, 20)); a.sort((x, y) => x - y); vcases.push(a); }
  for (const c of vcases) { assert.deepStrictEqual(n.dedupeSorted(c), o.dedupeSorted(c)); cnt++; }
  console.log("all equal, cases:", cnt);
})().catch(e => { console.error("FAIL", e.message); process.exit(1); });
